def are_anagrams(str1, str2):
    """
    This function checks if two strings are anagrams or not.
    An anagram is a word or phrase formed by rearranging the letters of a different word or phrase, typically using all the original letters exactly once.

    Args:
        str1 (str): The first string to compare.
        str2 (str): The second string to compare.

    Returns:
        bool: True if the strings are anagrams, False otherwise.
    """
    # Remove any white spaces and convert to lower case
    str1 = str1.replace(" ", "").lower()
    str2 = str2.replace(" ", "").lower()

    # Check if both strings have the same length
    if len(str1)!= len(str2):
        return False

    # Create a count dictionary for each string
    count_dict1 = {}
    count_dict2 = {}

    # Count the occurrences of each character in str1
    for char in str1:
        if char in count_dict1:
            count_dict1[char] += 1
        else:
            count_dict1[char] = 1

    # Count the occurrences of each character in str2
    for char in str2:
        if char in count_dict2:
            count_dict2[char] += 1
        else:
            count_dict2[char] = 1

    # Compare the count dictionaries
    for char, count in count_dict1.items():
        if char not in count_dict2 or count_dict2[char]!= count:
            return False

    return True
