def flatten_dict(dd, separator='_', prefix=''):
    """
    Flattens a dictionary of nested dictionaries.

    Args:
        dd (dict): The dictionary to flatten.
        separator (str, optional): The separator to use when joining keys. Defaults to '_'.
        prefix (str, optional): The prefix to use when joining keys. Defaults to ''.

    Returns:
        dict: The flattened dictionary.

    Example:
        >>> nested_dict = {'a': {'b': {'c': 1}, 'd': 2}, 'e': 3}
        >>> flatten_dict(nested_dict)
        {'a_b_c': 1, 'a_d': 2, 'e': 3}
    """
    flattened_dict = {}
    for key, value in dd.items():
        new_key = f"{prefix}{separator}{key}" if prefix else key
        if isinstance(value, dict):
            flattened_dict.update(flatten_dict(value, separator, new_key))
        else:
            flattened_dict[new_key] = value
    return flattened_dict

