class ItemModel:
    items = []

    def __init__(self, id, name):
        self.id = id
        self.name = name

    def json(self):
        return {
            'id': self.id,
            'name': self.name
        }

class ItemListResource(Resource):
    def get(self):
        return {'items': [item.json() for item in ItemModel.items]}

    def post(self):
        parser = reqparse.RequestParser()
        parser.add_argument('name', type=str, required=True, help="Name is required")
        args = parser.parse_args()

        ItemModel.items.append(ItemModel(len(ItemModel.items), args['name']))
        return {'message': 'Item created'}, 201

class ItemResource(Resource):
    def find_item_by_id(self, id):
        return next((item for item in ItemModel.items if item.id == id), None)

    def get(self, id):
        item = self.find_item_by_id(id)
        if item:
            return item.json()
        else:
            return {'message': 'Item not found'}, 404

    def put(self, id):
        item = self.find_item_by_id(id)
        if item:
            parser = reqparse.RequestParser()
            parser.add_argument('name', type=str, required=True, help="Name is required")
            args = parser.parse_args()

            item.name = args['name']
            return item.json()
        else:
            return {'message': 'Item not found'}, 404

    def delete(self, id):
        global ItemModel
        ItemModel.items = [item for item in ItemModel.items if item.id!= id]
        return {'message': 'Item deleted'}, 200

